APP_DIR = Path(__file__).resolve().parent
DATABASE_PATH = APP_DIR / "data" / "basal_heave_database_4200.csv"


@st.cache_resource(show_spinner=False)
def get_engine() -> BasalHeaveEngine:
    return BasalHeaveEngine(load_csv_database(DATABASE_PATH))


def basis_label(value: str) -> str:
    return {
        "lower": "Lower bound — conservative",
        "average": "Average of lower and upper bounds",
        "upper": "Upper bound",
    }[value]


def format_fs(value: float | None) -> str:
    return "Not valid" if value is None else f"{value:.3f}"



NC_REFERENCE_IMAGE_B64 = ""


def half_excavation_animation_html(
    *,
    H: float,
    B: float,
    q: float,
    Su: float,
    gamma: float,
    animate: bool,
) -> str:
    """
    Conceptual animated half-model.

    The animation shows the requested mechanism:
    - a broad curved failure surface starting at the excavation centreline,
      passing beneath the excavation and rising to an exterior vertical shear plane;
    - upward basal heave at excavation level;
    - downward ground-surface settlement outside the retaining wall.

    Displayed displacements are intentionally exaggerated for visual clarity.
    """
    settings = {
        "H": H,
        "B": B,
        "q": q,
        "Su": Su,
        "gamma": gamma,
        "animate": animate,
    }
    settings_json = json.dumps(settings)

    return f"""
    <!doctype html>
    <html lang="en">
    <head>
      <meta charset="utf-8" />
      <meta name="viewport" content="width=device-width, initial-scale=1" />
      <style>
        html, body {{ margin:0; padding:0; background:transparent; }}
        * {{ box-sizing:border-box; }}
        .card {{
          font-family:Inter,"Segoe UI",Arial,sans-serif;
          background:linear-gradient(145deg,#FFFDFC 0%,#FFF7F1 100%);
          border:1px solid #E8DCD5;
          border-radius:22px;
          padding:14px 16px 12px;
          box-shadow:0 12px 32px rgba(93,75,71,.08);
        }}
        .head {{
          display:flex;
          justify-content:space-between;
          align-items:flex-start;
          gap:12px;
          margin:2px 5px 9px;
        }}
        .title {{ color:#5C4B47; font-size:21px; font-weight:780; }}
        .subtitle {{
          color:#8A746E;
          font-size:12.5px;
          margin-top:4px;
          line-height:1.4;
        }}
        .pill {{
          color:#5C4B47;
          background:#F4E6DE;
          border:1px solid #E6CEC3;
          padding:6px 10px;
          border-radius:999px;
          font-size:11.5px;
          font-weight:750;
          white-space:nowrap;
        }}
        canvas {{ width:100%; height:auto; display:block; border-radius:15px; }}
        .note {{
          color:#8A746E;
          font-size:11.5px;
          line-height:1.45;
          margin:7px 7px 1px;
        }}
      </style>
    </head>
    <body>
      <div class="card">
        <div class="head">
          <div>
            <div class="title">Half excavation — animated basal-heave mechanism</div>
            <div class="subtitle">
              Symmetry half-model • settlement outside the wall and heave at excavation level
            </div>
          </div>
          <div class="pill">{"ANIMATED" if animate else "PAUSED"}</div>
        </div>

        <canvas id="model" width="1120" height="720"></canvas>

        <div class="note">
          Conceptual visualization only. The deformation is magnified and is not an
          Optum displacement output; the factors of safety remain calculated by the
          analytical equations and the Optum interpolation engine.
        </div>
      </div>

      <script>
        const S = {settings_json};
        const canvas = document.getElementById('model');
        const ctx = canvas.getContext('2d');
        const W = canvas.width;
        const HH = canvas.height;

        const C = {{
          bg:'#FFFDFC',
          soil:'#F1E3D7',
          soilDark:'#E5CABB',
          excavation:'#FFFDFC',
          mesh:'rgba(118,143,145,.68)',
          wall:'#52666A',
          strut:'#83A5A0',
          text:'#5C4B47',
          muted:'#8A746E',
          dim:'#6F8588',
          failure:'#C96862',
          failureSoft:'rgba(205,105,98,.17)',
          settlement:'#C78376',
          heave:'#D89382',
          surcharge:'#789B8E',
          centre:'#B8AAA4'
        }};

        const groundY = 112;
        const maxHalfWidth = 350;
        const maxDepth = 330;
        const scale = Math.min(maxHalfWidth / (S.B / 2), maxDepth / S.H);

        const halfWidth = (S.B / 2) * scale;
        const depth = S.H * scale;

        const centreX = 120;
        const wallX = centreX + halfWidth;
        const baseY = groundY + depth;
        const embed = Math.min(72, Math.max(38, depth * .18));
        const toeY = baseY + embed;

        const shearX = Math.min(
          1030,
          wallX + Math.max(165, halfWidth * .95, depth * .38)
        );
        const xMax = 1080;
        const yMax = 665;

        // Terzaghi-style half mechanism:
        // 45-degree wedge + smooth circular-looking arc + vertical shear plane.
        const wallToe = {{x:wallX, y:baseY}};
        const wedgeDrop = Math.min(
          halfWidth,
          Math.max(60, yMax - baseY - 76)
        );
        const wedge = {{
          x:centreX,
          y:baseY + wedgeDrop
        }};
        const end = {{
          x:shearX,
          y:baseY + wedgeDrop * .70
        }};
        const arcCtrl = {{
          x:centreX + (shearX - centreX) * .53,
          y:Math.min(
            yMax - 25,
            baseY + wedgeDrop * 1.36
          )
        }};

        function quadraticPoint(p0,p1,p2,t) {{
          const u=1-t;
          return {{
            x:u*u*p0.x + 2*u*t*p1.x + t*t*p2.x,
            y:u*u*p0.y + 2*u*t*p1.y + t*t*p2.y
          }};
        }}

        function slipPoint(t) {{
          return quadraticPoint(wedge,arcCtrl,end,t);
        }}

        function distanceToSegment(px,py,a,b) {{
          const vx=b.x-a.x;
          const vy=b.y-a.y;
          const wx=px-a.x;
          const wy=py-a.y;
          const vv=vx*vx+vy*vy;
          const raw=vv > 0 ? (wx*vx+wy*vy)/vv : 0;
          const u=Math.max(0,Math.min(1,raw));
          const sx=a.x+u*vx;
          const sy=a.y+u*vy;
          return Math.hypot(px-sx,py-sy);
        }}

        function roundedRect(x,y,w,h,r,fill,stroke=null) {{
          ctx.beginPath();
          ctx.roundRect(x,y,w,h,r);
          if(fill) {{
            ctx.fillStyle=fill;
            ctx.fill();
          }}
          if(stroke) {{
            ctx.strokeStyle=stroke;
            ctx.stroke();
          }}
        }}

        function arrow(x1,y1,x2,y2,color,width=2.5,head=8) {{
          const a=Math.atan2(y2-y1,x2-x1);
          ctx.strokeStyle=color;
          ctx.fillStyle=color;
          ctx.lineWidth=width;
          ctx.beginPath();
          ctx.moveTo(x1,y1);
          ctx.lineTo(x2,y2);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(x2,y2);
          ctx.lineTo(
            x2-head*Math.cos(a-Math.PI/6),
            y2-head*Math.sin(a-Math.PI/6)
          );
          ctx.lineTo(
            x2-head*Math.cos(a+Math.PI/6),
            y2-head*Math.sin(a+Math.PI/6)
          );
          ctx.closePath();
          ctx.fill();
        }}

        function dimension(x1,y1,x2,y2,label,vertical=false) {{
          ctx.save();
          ctx.strokeStyle=C.dim;
          ctx.fillStyle=C.dim;
          ctx.lineWidth=1.8;
          arrow(x1,y1,x2,y2,C.dim,1.8,7);
          arrow(x2,y2,x1,y1,C.dim,1.8,7);
          ctx.font='700 16px Segoe UI';

          if(vertical) {{
            ctx.translate(x1-18,(y1+y2)/2);
            ctx.rotate(-Math.PI/2);
            const tw=ctx.measureText(label).width;
            roundedRect(-tw/2-8,-14,tw+16,28,14,'#FFF8F3','#E5D7D0');
            ctx.fillStyle=C.text;
            ctx.textAlign='center';
            ctx.fillText(label,0,6);
          }} else {{
            const mx=(x1+x2)/2;
            const my=y1-15;
            const tw=ctx.measureText(label).width;
            roundedRect(mx-tw/2-8,my-18,tw+16,28,14,'#FFF8F3','#E5D7D0');
            ctx.fillStyle=C.text;
            ctx.textAlign='center';
            ctx.fillText(label,mx,my+2);
          }}
          ctx.restore();
        }}

        function settlementAt(x,p) {{
          if(x < wallX) return 0;
          const centre = wallX + (shearX-wallX)*.48;
          const width = Math.max(105,(shearX-wallX)*.58);
          const z=(x-centre)/width;
          const main=20*p*Math.exp(-2.0*z*z);
          const nearWall=5*p*Math.exp(
            -Math.pow((x-wallX)/Math.max(70,(shearX-wallX)*.34),2)
          );
          const farTaper=Math.max(0,Math.min(1,(xMax-x)/130));
          return (main+nearWall)*farTaper;
        }}

        function heaveAt(x,p) {{
          if(x < centreX || x > wallX) return 0;
          const s=(x-centreX)/(wallX-centreX);
          // Maximum heave at the symmetry centreline; zero at the retaining wall.
          return 22*p*Math.pow(Math.cos(Math.PI*s/2),1.25);
        }}

        // Triangular mesh.
        const dx=42;
        const dy=37;
        const cols=Math.ceil((xMax-centreX)/dx)+1;
        const rows=Math.ceil((yMax-groundY)/dy)+1;
        const nodes=[];

        for(let j=0;j<rows;j++) {{
          const row=[];
          for(let i=0;i<cols;i++) {{
            const jitterX=((i*17+j*11)%9-4)*1.7;
            const jitterY=((i*7+j*19)%9-4)*1.3;
            row.push({{
              x:centreX+i*dx+jitterX,
              y:groundY+j*dy+jitterY
            }});
          }}
          nodes.push(row);
        }}

        function inExcavation(x,y) {{
          return x < wallX-3 && y > groundY-2 && y < baseY-1;
        }}

        function displacement(p,x,y) {{
          // Basal heave below the excavation.
          const bx=(x-(centreX+halfWidth*.38))/Math.max(halfWidth*.72,85);
          const by=(y-(baseY+42))/Math.max(depth*.44,105);
          const basal=Math.exp(-(bx*bx+by*by));

          // Retained soil settles and moves toward the excavation.
          const rx=(x-(wallX+(shearX-wallX)*.45))/Math.max((shearX-wallX)*.65,105);
          const ry=(y-(groundY+depth*.34))/Math.max(depth*.72,135);
          const retained=Math.exp(-(rx*rx+ry*ry));
          const retainedMask=(x>=wallX && x<=shearX+55)?1:0;

          // Localized deformation near the requested failure surface.
          let minD=9999;
          for(let k=0;k<=60;k++) {{
            const b=slipPoint(k/60);
            const d=Math.hypot(x-b.x,y-b.y);
            if(d<minD) minD=d;
          }}
          minD=Math.min(
            minD,
            distanceToSegment(x,y,wallToe,wedge)
          );
          if(x>=shearX) {{
            const verticalDistance=Math.abs(x-shearX);
            const withinVertical=(y>=groundY && y<=end.y)?1:0;
            if(withinVertical) minD=Math.min(minD,verticalDistance);
          }}
          const slip=Math.exp(-(minD*minD)/(2*64*64));

          let ux=0;
          let uy=0;

          ux += -8.0*basal*p;
          uy += -24.0*basal*p;

          ux += -13.0*retained*retainedMask*p;
          uy +=  16.0*retained*retainedMask*p;

          ux += -5.5*slip*p;
          uy +=  1.5*slip*p;

          // Ground nodes follow the visible settlement trough.
          const topInfluence=Math.exp(
            -Math.pow((y-groundY)/Math.max(42,depth*.20),2)
          );
          uy += settlementAt(x,p)*topInfluence;

          // Symmetry boundary: zero horizontal movement.
          if(Math.abs(x-centreX)<18) ux=0;

          // Far-field restraint.
          const far=Math.max(0,Math.min(1,(xMax-x)/145));
          ux*=far;
          uy*=far;

          return {{x:x+ux,y:y+uy}};
        }}

        function drawTriangle(a,b,c,p) {{
          const cx=(a.x+b.x+c.x)/3;
          const cy=(a.y+b.y+c.y)/3;
          if(inExcavation(cx,cy)) return;

          const A=displacement(p,a.x,a.y);
          const B=displacement(p,b.x,b.y);
          const D=displacement(p,c.x,c.y);

          ctx.beginPath();
          ctx.moveTo(A.x,A.y);
          ctx.lineTo(B.x,B.y);
          ctx.lineTo(D.x,D.y);
          ctx.closePath();
          ctx.strokeStyle=C.mesh;
          ctx.lineWidth=1.12;
          ctx.stroke();
        }}

        function drawFailureSurface(dashOffset) {{
          ctx.save();
          ctx.beginPath();
          ctx.moveTo(wallToe.x,wallToe.y);
          ctx.lineTo(wedge.x,wedge.y);
          ctx.quadraticCurveTo(
            arcCtrl.x,arcCtrl.y,
            end.x,end.y
          );
          ctx.lineTo(shearX,groundY);
          ctx.lineWidth=4.6;
          ctx.strokeStyle=C.failure;
          ctx.setLineDash([15,9]);
          ctx.lineDashOffset=-dashOffset;
          ctx.lineJoin='round';
          ctx.lineCap='round';
          ctx.stroke();
          ctx.restore();
        }}

        function drawGroundSurface(p) {{
          // Remove soil above the settled ground profile.
          ctx.save();
          ctx.beginPath();
          ctx.moveTo(wallX,groundY);
          ctx.lineTo(xMax,groundY);
          for(let x=xMax;x>=wallX;x-=8) {{
            ctx.lineTo(x,groundY+settlementAt(x,p));
          }}
          ctx.closePath();
          ctx.fillStyle=C.bg;
          ctx.fill();
          ctx.restore();

          // Deformed ground line.
          ctx.beginPath();
          for(let x=wallX;x<=xMax;x+=6) {{
            const y=groundY+settlementAt(x,p);
            if(x===wallX) ctx.moveTo(x,y);
            else ctx.lineTo(x,y);
          }}
          ctx.strokeStyle=C.dim;
          ctx.lineWidth=2.5;
          ctx.stroke();
        }}

        function drawHeavedBase(p) {{
          // Fill the soil bulge entering the excavation.
          ctx.beginPath();
          ctx.moveTo(centreX,baseY);
          for(let x=centreX;x<=wallX;x+=5) {{
            ctx.lineTo(x,baseY-heaveAt(x,p));
          }}
          ctx.lineTo(wallX,baseY);
          ctx.closePath();
          ctx.fillStyle=C.soilDark;
          ctx.fill();

          ctx.beginPath();
          for(let x=centreX;x<=wallX;x+=5) {{
            const y=baseY-heaveAt(x,p);
            if(x===centreX) ctx.moveTo(x,y);
            else ctx.lineTo(x,y);
          }}
          ctx.strokeStyle=C.heave;
          ctx.lineWidth=4.2;
          ctx.stroke();
        }}

        function drawFrame(time) {{
          const pulse=S.animate
            ? (1-Math.cos(time/1050*Math.PI))/2
            : .82;
          const dash=S.animate ? time/24 : 0;

          ctx.clearRect(0,0,W,HH);
          ctx.fillStyle=C.bg;
          ctx.fillRect(0,0,W,HH);

          // Soil mass and excavation void.
          ctx.fillStyle=C.soil;
          ctx.fillRect(centreX,groundY,xMax-centreX,yMax-groundY);
          ctx.fillStyle=C.excavation;
          ctx.fillRect(centreX,groundY,wallX-centreX,baseY-groundY);

          // Conceptual moving failure block following the Terzaghi mechanism.
          ctx.save();
          ctx.beginPath();
          ctx.moveTo(wallToe.x,wallToe.y);
          ctx.lineTo(wedge.x,wedge.y);
          ctx.quadraticCurveTo(
            arcCtrl.x,arcCtrl.y,
            end.x,end.y
          );
          ctx.lineTo(shearX,groundY);
          ctx.lineTo(wallX,groundY);
          ctx.lineTo(wallToe.x,wallToe.y);
          ctx.closePath();
          ctx.fillStyle=C.failureSoft;
          ctx.fill();
          ctx.restore();

          // Deformed triangular mesh.
          for(let j=0;j<rows-1;j++) {{
            for(let i=0;i<cols-1;i++) {{
              const a=nodes[j][i];
              const b=nodes[j][i+1];
              const c=nodes[j+1][i];
              const d=nodes[j+1][i+1];

              if((i+j)%2===0) {{
                drawTriangle(a,b,d,pulse);
                drawTriangle(a,d,c,pulse);
              }} else {{
                drawTriangle(a,b,c,pulse);
                drawTriangle(b,d,c,pulse);
              }}
            }}
          }}

          drawGroundSurface(pulse);
          drawHeavedBase(pulse);

          // Symmetry centreline.
          ctx.save();
          ctx.strokeStyle=C.centre;
          ctx.setLineDash([8,7]);
          ctx.lineWidth=2;
          ctx.beginPath();
          ctx.moveTo(centreX,55);
          ctx.lineTo(centreX,yMax);
          ctx.stroke();
          ctx.restore();

          ctx.fillStyle=C.muted;
          ctx.font='600 13px Segoe UI';
          ctx.fillText('C/L — symmetry',centreX+8,78);

          // Retaining wall.
          const toeShift=-7*pulse;
          ctx.strokeStyle=C.wall;
          ctx.lineWidth=9;
          ctx.lineCap='round';
          ctx.beginPath();
          ctx.moveTo(wallX,groundY+settlementAt(wallX,pulse));
          ctx.quadraticCurveTo(
            wallX-1.5*pulse,
            baseY,
            wallX+toeShift,
            toeY
          );
          ctx.stroke();

          // Half struts.
          const levels=[.24,.51,.78];
          ctx.strokeStyle=C.strut;
          ctx.lineWidth=7;
          ctx.lineCap='round';

          for(const f of levels) {{
            const y=groundY+depth*f;
            const wallAt=wallX-4*pulse*f*f;
            ctx.beginPath();
            ctx.moveTo(centreX+7,y);
            ctx.lineTo(wallAt-5,y);
            ctx.stroke();
            ctx.fillStyle=C.wall;
            ctx.beginPath();
            ctx.arc(wallAt-5,y,5,0,Math.PI*2);
            ctx.fill();
          }}

          drawFailureSurface(dash);

          // Basal-heave arrows.
          const heaveArrowX=centreX+halfWidth*.25;
          arrow(
            heaveArrowX,
            baseY+34,
            heaveArrowX,
            baseY-43-11*pulse,
            C.failure,
            3.3,
            10
          );
          arrow(
            centreX+halfWidth*.57,
            baseY+25,
            centreX+halfWidth*.57,
            baseY-26-8*pulse,
            C.failure,
            2.8,
            9
          );

          // Ground-settlement arrows.
          const settleXs=[
            wallX+(shearX-wallX)*.28,
            wallX+(shearX-wallX)*.53,
            wallX+(shearX-wallX)*.78
          ];

          for(const x of settleXs) {{
            const gy=groundY+settlementAt(x,pulse);
            arrow(x,gy-48,x,gy-5,C.settlement,2.7,9);
          }}

          ctx.fillStyle=C.text;
          ctx.font='700 14px Segoe UI';
          ctx.fillText(
            'GROUND-SURFACE SETTLEMENT',
            Math.min(xMax-265,wallX+45),
            groundY+52
          );
          ctx.fillText(
            'BASAL HEAVE',
            centreX+20,
            baseY-54
          );

          // Uniform surcharge follows the retained ground profile.
          for(let x=wallX+45;x<Math.min(xMax-35,wallX+310);x+=55) {{
            const gy=groundY+settlementAt(x,pulse);
            arrow(x,gy-68,x,gy-15,C.surcharge,2.35,8);
          }}

          ctx.fillStyle=C.text;
          ctx.font='700 15px Segoe UI';
          ctx.fillText(
            `q = ${{S.q.toFixed(1)}} kPa`,
            Math.min(xMax-150,wallX+58),
            35
          );

          // Dimensions.
          ctx.strokeStyle=C.dim;
          ctx.lineWidth=1.3;
          ctx.beginPath();
          ctx.moveTo(centreX,groundY-8);
          ctx.lineTo(centreX,18);
          ctx.moveTo(wallX,groundY-8);
          ctx.lineTo(wallX,18);
          ctx.stroke();
          dimension(
            centreX,
            28,
            wallX,
            28,
            `B/2 = ${{(S.B/2).toFixed(2)}} m`
          );

          ctx.beginPath();
          ctx.moveTo(centreX-10,groundY);
          ctx.lineTo(52,groundY);
          ctx.moveTo(centreX-10,baseY);
          ctx.lineTo(52,baseY);
          ctx.stroke();
          dimension(
            63,
            groundY,
            63,
            baseY,
            `H = ${{S.H.toFixed(2)}} m`,
            true
          );

          // Given-input badge.
          roundedRect(
            730,560,342,70,15,
            'rgba(255,249,245,.95)',
            '#E4D6CE'
          );
          ctx.fillStyle=C.text;
          ctx.font='750 14px Segoe UI';
          ctx.fillText(
            `Given full width B = ${{S.B.toFixed(2)}} m`,
            750,586
          );
          ctx.fillText(
            `Su = ${{S.Su.toFixed(1)}} kPa   γ = ${{S.gamma.toFixed(1)}} kN/m³`,
            750,611
          );

          ctx.fillStyle=C.muted;
          ctx.font='600 12px Segoe UI';
          ctx.fillText(
            'Conceptual deformed mesh — displacement magnified',
            138,655
          );

          if(S.animate) requestAnimationFrame(drawFrame);
        }}

        requestAnimationFrame(drawFrame);
      </script>
    </body>
    </html>
    """



st.set_page_config(
    page_title="Basal Heave Stability Calculator",
    page_icon="🏗️",
    layout="wide",
)

st.markdown(
    """
    <style>
      :root {
        --page: #FCF9F7;
        --card: #FFFDFC;
        --card-soft: #FFF7F2;
        --line: #EADDD5;
        --text: #5D4B47;
        --muted: #8A746E;
        --accent: #B98778;
        --accent-dark: #96685C;
      }
      .stApp {
        background:
          radial-gradient(circle at 10% 5%, rgba(240,219,207,.27), transparent 28%),
          linear-gradient(180deg,#FFFDFC 0%,var(--page) 100%);
        color:var(--text);
      }
      .block-container { max-width:1500px; padding-top:1.45rem; padding-bottom:3rem; }
      h1,h2,h3,h4,p,label { color:var(--text); }
      [data-testid="stCaptionContainer"] { color:var(--muted); }
      [data-testid="stMetric"] {
        background:linear-gradient(145deg,#FFFDFC 0%,#FFF7F2 100%);
        border:1px solid var(--line); border-radius:18px; padding:16px 18px;
        box-shadow:0 8px 24px rgba(93,75,71,.06);
      }
      [data-testid="stMetricLabel"] { color:var(--muted); }
      [data-testid="stExpander"] {
        background:rgba(255,253,252,.80); border:1px solid var(--line);
        border-radius:16px; overflow:hidden;
      }
      [data-testid="stDataFrame"] { border:1px solid var(--line); border-radius:16px; overflow:hidden; }
      div[data-baseweb="input"] > div, div[data-baseweb="select"] > div {
        background:#FFFDFC; border-color:#DDC9BF; border-radius:12px;
      }
      .stDownloadButton > button {
        border:1px solid #D4B8AB; border-radius:12px;
        background:linear-gradient(145deg,#C99A8A,#B98778); color:white; font-weight:700;
      }
      [data-testid="stAlert"] { border-radius:14px; }
      hr { border-color:var(--line); }
      .scope-box {
        background:linear-gradient(145deg,#FFF9F5,#FFFDFC); border:1px solid var(--line);
        border-left:5px solid var(--accent); border-radius:14px; padding:.9rem 1.1rem;
        margin:.5rem 0 1rem; color:var(--text);
      }
      .section-note {
        background:#FFF8F4; border:1px solid var(--line); border-radius:14px;
        color:var(--muted); padding:12px 15px; line-height:1.55;
      }
    </style>
    """,
    unsafe_allow_html=True,
)

engine = get_engine()

st.title("Basal Heave Stability Calculator")
st.caption(
    "Terzaghi and Bjerrum & Eide are calculated analytically • "
    "only the Optum bounds are interpolated from the numerical database"
)

with st.expander("Calculation basis and database scope", expanded=False):
    st.markdown(
        """
        <div class="scope-box">
          <b>Optum interpolation scope:</b>
          Su = 5–60 kPa; γ = 16–20 kN/m³; q = 0–20 kPa;
          H = 6–14 m; B = 4–30 m; R<sub>int</sub> = 1.0.
        </div>
        """,
        unsafe_allow_html=True,
    )
    st.write(
        "The database is used only for the Optum lower and upper bounds. "
        "The two classical factors of safety and Nc are recalculated for every input."
    )
    st.write(
        "The only absent Optum corner is q = 20 kPa with Su = 5 kPa. "
        "For 10 < q ≤ 20 kPa, the supported boundary is Su ≥ q/2."
    )

st.subheader("Given input parameters")

input_cols = st.columns(5)
with input_cols[2]:
    q = st.number_input(
        "Uniform surcharge, q (kPa)", min_value=0.0, max_value=20.0,
        value=10.0, step=1.0,
    )

minimum_su = engine.minimum_su_for_q(q)
with input_cols[0]:
    Su = st.number_input(
        "Undrained shear strength, Su (kPa)",
        min_value=float(minimum_su), max_value=60.0,
        value=max(20.0, float(minimum_su)), step=1.0,
        help=f"The Optum database requires Su ≥ {minimum_su:g} kPa when q = {q:g} kPa.",
    )
with input_cols[1]:
    gamma = st.number_input(
        "Total unit weight, γ (kN/m³)", min_value=16.0, max_value=20.0,
        value=18.0, step=0.5,
    )
with input_cols[3]:
    H = st.number_input(
        "Excavation depth, H (m)", min_value=6.0, max_value=14.0,
        value=10.0, step=0.5,
    )
with input_cols[4]:
    B = st.number_input(
        "Full excavation width, B (m)", min_value=4.0, max_value=30.0,
        value=10.0, step=0.5,
    )

settings_cols = st.columns([1.45, 1.0, 1.0])
with settings_cols[0]:
    recommendation_basis = st.selectbox(
        "Recommended Optum value", options=["lower", "average", "upper"],
        format_func=basis_label, index=1,
    )
with settings_cols[1]:
    target_fs = st.number_input("Target F.S.", min_value=0.0, value=1.50, step=0.05)
with settings_cols[2]:
    animate_mechanism = st.toggle("Animate deformation", value=True)

try:
    result = engine.calculate(
        Su=Su, gamma=gamma, q=q, H=H, B=B,
        recommendation_basis=recommendation_basis,
    )
except DatabaseError as exc:
    st.error(str(exc))
    st.stop()

st.divider()
st.subheader("Calculated factors of safety")

main_results = st.columns(3)
main_results[0].metric("Terzaghi F.S. — equation", format_fs(result["terzaghi"]))
main_results[1].metric("Bjerrum & Eide F.S. — equation", f"{result['bjerrum']:.3f}")
main_results[2].metric("Recommended Optum F.S. — interpolation", f"{result['recommended']:.3f}")

if result["terzaghi"] is None:
    st.warning(
        "The Terzaghi denominator is zero or negative for this input "
        f"({result['terzaghi_denominator']:.3f} kPa), so a positive Terzaghi F.S. is not reported."
    )

optum_results = st.columns(4)
optum_results[0].metric("Optum lower bound", f"{result['numerical_lower']:.3f}")
optum_results[1].metric("Optum average", f"{result['numerical_average']:.3f}")
optum_results[2].metric("Optum upper bound", f"{result['numerical_upper']:.3f}")
optum_results[3].metric("Upper–lower gap", f"{result['bound_gap_percent']:.1f}%")

difference = result["recommended"] - target_fs
if difference >= 0:
    st.success(f"The recommended Optum F.S. is {difference:.3f} above the target of {target_fs:.2f}.")
else:
    st.error(f"The recommended Optum F.S. is {abs(difference):.3f} below the target of {target_fs:.2f}.")

# No equations are displayed externally. Nc is communicated through the graph.
visual_col, nc_col = st.columns([1.65, 1.0], gap="large")
with visual_col:
    st.subheader("Half excavation and animated failure mechanism")
    components.html(
        half_excavation_animation_html(
            H=H, B=B, q=q, Su=Su, gamma=gamma, animate=animate_mechanism,
        ),
        height=770,
        scrolling=False,
    )
with nc_col:
    st.subheader("Nc reference graph")
    st.image(
        nc_reference_image_bytes(),
        caption="Bjerrum & Eide / Skempton reference chart",
        use_container_width=True,
    )

calculation_details = pd.DataFrame(
    [
        ["H/B", result["H_over_B"], "—"],
        ["B/H", result["B_over_H"], "—"],
        ["Half-model width", B / 2.0, "m"],
        ["B₁", result["B1"], "m"],
        ["γH + q", result["driving_pressure"], "kPa"],
        ["Terzaghi denominator", result["terzaghi_denominator"], "kPa"],
        ["Bjerrum Nc", result["Nc"], "—"],
        ["Optum recommendation basis", basis_label(recommendation_basis), "—"],
    ],
    columns=["Quantity", "Value", "Unit"],
)
st.dataframe(calculation_details, use_container_width=True, hide_index=True)

st.markdown(
    """
    <div class="section-note">
      <b>Visual interpretation:</b> only one half of the excavation is shown because the section is symmetric.
      The animated mesh represents an exaggerated deformation pattern, not a calculated Optum displacement field.
      The dashed curve is a conceptual basal-heave surface matching the requested geometry.
    </div>
    """,
    unsafe_allow_html=True,
)

st.subheader("Nearest original Optum models")
nearest = pd.DataFrame(engine.nearest_cases(Su=Su, gamma=gamma, q=q, H=H, B=B, count=8))
st.dataframe(nearest, use_container_width=True, hide_index=True)

export_rows = [
    ("Su (kPa)", result["Su"]),
    ("gamma (kN/m3)", result["gamma"]),
    ("q (kPa)", result["q"]),
    ("H (m)", result["H"]),
    ("Full B (m)", result["B"]),
    ("Half-model width B/2 (m)", result["B"] / 2.0),
    ("H/B", result["H_over_B"]),
    ("B/H", result["B_over_H"]),
    ("B1 (m)", result["B1"]),
    ("Terzaghi F.S. calculated analytically", result["terzaghi"]),
    ("Terzaghi denominator (kPa)", result["terzaghi_denominator"]),
    ("Bjerrum Nc calculated analytically", result["Nc"]),
    ("Bjerrum & Eide F.S. calculated analytically", result["bjerrum"]),
    ("Optum lower bound interpolated", result["numerical_lower"]),
    ("Optum average interpolated", result["numerical_average"]),
    ("Optum upper bound interpolated", result["numerical_upper"]),
    ("Recommended Optum F.S.", result["recommended"]),
    ("Recommendation basis", basis_label(recommendation_basis)),
    ("Upper-lower gap (%)", result["bound_gap_percent"]),
    ("Target F.S.", target_fs),
]
buffer = io.StringIO()
writer = csv.writer(buffer)
writer.writerow(["Item", "Value"])
writer.writerows(export_rows)
st.download_button(
    "Download calculation as CSV",
    data=buffer.getvalue().encode("utf-8"),
    file_name="basal_heave_calculation.csv",
    mime="text/csv",
    use_container_width=True,
)

st.divider()
st.subheader("Applicability")
st.markdown(
    """
- Homogeneous clay with constant undrained shear strength.
- Undrained total-stress condition.
- The wall, supports, groundwater, boundaries, and hard-stratum condition must match the numerical study.
- Optum interpolation is blocked outside the data-supported domain.
- The target F.S. is user-defined and is not presented as a universal code requirement.
"""
)
